      "name": "Communication clarity",
      "hypothesis": "Clear and structured responses improve the candidate's chances of receiving a job offer",
      "predicted_direction": "increase",
      "treatment_values": ["Well-organized answers", "Disorganized responses", "Concise and focused"]
    },
    {
      "name": "Legal experience",
      "hypothesis": "Candidates with relevant legal experience are more likely to be offered the job",
      "predicted_direction": "increase",
