    },
    {
      "name": "Confidence level",
      "hypothesis": "Higher confidence during the interview correlates with a greater likelihood of receiving a job offer",
      "predicted_direction": "increase",
      "treatment_values": ["High confidence", "Moderate confidence", "Low confidence"]
    }
  ],
