  "schema_version": "scientist-design-v1",
  "scenario": "3 bidders participating in an auction for a piece of art starting at fifty dollars",
  "agents": [
    {
      "name": "Agent1",
      "role": "Conservative Collector",
      "goal": "Maximize profit while minimizing risk",
      "constraints": ["Bids only if confident in value"]
    },
    {
      "name": "Agent2",
      "role": "Speculative Investor",
      "goal": "Achieve high returns through strategic bidding",
      "constraints": ["Limits bids to 150% of starting price"]
    },
    {
      "name": "Agent3",
      "role": "Art Enthusiast",
      "goal": "Acquire the art regardless of cost",
      "constraints": ["Bids up to 200% of starting price"]
    }
  ],
  "outcome": {
    "name": "Final Bid Price",
    "operationalization": "The highest bid submitted by any agent at the end of the auction",
    "measurement_question": "What is the final price paid for the art?",
    "respondent": "Agent who submitted the winning bid"
  },
  "causes": [
    {
      "name": "Bidder's Risk Tolerance",
      "hypothesis": "Higher risk tolerance leads to higher final bid price",
      "predicted_direction": "increase",
      "treatment_values": ["Low", "Medium", "High"]
    },
    {
      "name": "Starting Price",
      "hypothesis": "A higher starting price increases the final bid price",
      "predicted_direction": "increase",
      "treatment_values": ["$50", "$75", "$100"]
    },
    {
      "name": "Previous Auction Experience",
      "hypothesis": "More experience leads to more aggressive bidding",
      "predicted_direction": "increase",
      "treatment_values": ["Novice", "Intermediate", "Expert"]
    }
  ],
  "information_scope": {
    "public": ["Current highest bid", "Starting price", "Number of bidders"],
    "private": [
      {
        "agent": "Agent1",
        "information": ["Agent1's maximum bid", "Agent1's risk tolerance"]
      },
      {
        "agent": "Agent2",
        "information": ["Agent2's maximum bid", "Agent2's previous auction experience"]
      },
      {
        "agent": "Agent3",
        "information": ["Agent3's maximum bid", "Agent3's interest in the art"]
      }
    ]
  },
  "interaction": {
    "order": ["Agent1", "Agent2", "Agent3"],
    "max_turns": 3,
    "stopping_rule": "Auction ends when no further bids are placed"
  }
}

